  if (!document.getElementById('em-css')) { css = document.createElement('style'); css.id = 'em-css'; css.textContent = CSS; document.head.appendChild(css); }
  const me = () => map.player.pos(), dist = (x, z) => { const m = me(); return Math.hypot(x - m.x, z - m.z); };
