  function siren(k) { if (k === 'police') { for (let i = 0; i < 4; i++) { tone(880, i * 0.5, 0.22, 'square', 0.035); tone(660, i * 0.5 + 0.25, 0.22, 'square', 0.035); } }   /* 112 = 짧게 높낮이 넷 · 119 구급 = 길게 오르내림 */
    else if (k === 'forest') { tone(660, 0, 0.3, 'triangle', 0.045); tone(880, 0.35, 0.45, 'triangle', 0.045); }   /* 산림 감시 = 짧은 두 음(놀래기 X) */
    else if (k === 'sea') { for (let i = 0; i < 2; i++) { tone(523, i * 0.9, 0.35, 'triangle', 0.045); tone(784, i * 0.9 + 0.38, 0.45, 'triangle', 0.045); } }   /* 해양경찰 바닷가 안내 = 낮고 긴 두 음 두 번 */
    else if (k === 'pet') { tone(784, 0, 0.16, 'triangle', 0.045); tone(988, 0.2, 0.16, 'triangle', 0.045); tone(784, 0.4, 0.26, 'triangle', 0.045); }   /* 보호센터 전화 = 짧은 세 음 */
    else { for (let i = 0; i < 3; i++) { tone(700, i * 0.8, 0.4, 'triangle', 0.06, 960); tone(960, i * 0.8 + 0.4, 0.4, 'triangle', 0.06, 700); } } }

